class Media {
  #duree;
  constructor(titre, duree) {
    this.titre = titre;
    this.duree = duree; // passe par le setter
  }
  get duree() {
    return this.#duree;
  }
  set duree(valeur) {
    if (typeof valeur !== "number" || valeur <= 0) {
      throw new RangeError("Durée invalide");
    }
    this.#duree = valeur;
  }
}

class Video extends Media {
  constructor(titre, auteur, duree) {
    super(titre, auteur);
    this.duree = duree;
  }
  decrire() {
    return "[video] " + super.decrire() + " (" + this.duree + "s)";
  }
}

